import json

OUT = "/Users/yuluo/Desktop/game/games_test/reverse-engineering/tiny-glade/evidence/toolchain/clutter/"
prog = currentProgram
addr = prog.getAddressFactory().getAddress("0x1422d6ed0")
fm = prog.getFunctionManager()
f = fm.getFunctionAt(addr)
if f is None:
    raise RuntimeError("absent")
listing = prog.getListing()
body = f.getBody()
it = listing.getInstructions(body, True)
refmgr = prog.getReferenceManager()
calls = {}
branches = []
leas = []
insn_count = 0
while it.hasNext():
    monitor.checkCancelled()
    ins = it.next()
    insn_count += 1
    a = ins.getAddress()
    mnem = ins.getMnemonicString()
    if mnem == "CALL":
        for r in refmgr.getReferencesFrom(a):
            if r.getReferenceType().isCall():
                to = r.getToAddress()
                tgt = fm.getFunctionAt(to)
                nm = str(tgt.getName()) if tgt else str(to)
                key = nm + "@" + str(to)
                if key not in calls:
                    calls[key] = [0, []]
                calls[key][0] += 1
                calls[key][1].append(str(a))
    elif mnem.startswith("J"):
        for r in refmgr.getReferencesFrom(a):
            if r.getReferenceType().isJump():
                branches.append([str(a), mnem, str(r.getToAddress())])
    elif mnem == "LEA":
        # record lea with memory reference target if any
        for r in refmgr.getReferencesFrom(a):
            if r.getReferenceType().isData() or r.getReferenceType().isUninitialized():
                leas.append([str(a), str(r.getToAddress())])
out = {"insn_count": insn_count, "calls": calls, "branches": branches, "leas": leas}
open(OUT + "populate_calls_branches.json", "w").write(json.dumps(out, indent=1))
print(json.dumps({"insn_count": insn_count, "n_calls": len(calls), "n_branches": len(branches), "n_leas": len(leas)}))
